<?php

declare(strict_types=1);
require_once dirname(__DIR__,2).'/config.php';require_once ROOT_PATH.'/database/config/db.php';require_once ROOT_PATH.'/security/middleware/AuthMiddleware.php';require_once ROOT_PATH.'/services/CoworkspaceService.php';require_once ROOT_PATH.'/services/OnlyOfficeService.php';
AuthMiddleware::startSession();$user=AuthMiddleware::requireAuth();$db=Database::getInstance();$uid=(int)$user['id'];$documentId=(int)($_GET['id']??0);$workspaceId=(int)($_GET['workspace_id']??0);if($documentId<1||$workspaceId<1){http_response_code(400);exit('Document and Coworkspace are required.');}
try{$workspace=CoworkspaceService::get($db,$workspaceId,$uid);$stmt=$db->prepare('SELECT d.* FROM collab_documents d WHERE d.id=:did AND d.workspace_id=:wid LIMIT 1');$stmt->execute([':did'=>$documentId,':wid'=>$workspaceId]);$document=$stmt->fetch(PDO::FETCH_ASSOC);if(!$document)throw new RuntimeException('Document not found.',404);$stmt=$db->prepare('SELECT permission FROM collab_resource_permissions WHERE resource_type="document" AND resource_id=:rid AND user_id=:uid LIMIT 1');$stmt->execute([':rid'=>$documentId,':uid'=>$uid]);$explicit=$stmt->fetchColumn();$isOwner=(int)$document['created_by']===$uid||(int)$workspace['host_id']===$uid;if(!$isOwner&&(string)$document['visibility']==='private'&&$explicit===false)throw new RuntimeException('This private document has not been shared with you.',403);$role=(string)($workspace['member_role']??'');$canEdit=$isOwner||$explicit==='edit'||((string)$document['visibility']==='public'&&in_array($role,['host','editor','member'],true)&&(int)$workspace['allow_edit_documents']===1);$canDelete=$isOwner||in_array($role,['host','editor'],true);$documentType=match((string)$document['file_type']){'xlsx'=>'cell','pptx'=>'slide',default=>'word'};$displayName=(string)($user['full_name']??$user['username']??'User');$config=['documentType'=>$documentType,'document'=>['fileType'=>(string)$document['file_type'],'key'=>(string)$document['document_key'],'title'=>(string)$document['file_name'],'url'=>OnlyOfficeService::signedFileUrl($documentId,(string)$document['document_key']),'permissions'=>['edit'=>$canEdit,'download'=>true,'print'=>true,'comment'=>true,'review'=>true]],'editorConfig'=>['mode'=>$canEdit?'edit':'view','callbackUrl'=>OnlyOfficeService::callbackUrl($documentId),'user'=>['id'=>(string)$uid,'name'=>$displayName]],'height'=>'100%','width'=>'100%','type'=>'desktop'];$config['token']=OnlyOfficeService::sign($config);$documentServer=OnlyOfficeService::documentServerUrl();if($documentServer==='')throw new RuntimeException('ONLYOFFICE_DOCUMENT_SERVER_URL is not configured.');}catch(Throwable $e){$status=(int)$e->getCode();http_response_code(($status>=400&&$status<600)?$status:500);exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars((string)$document['title'],ENT_QUOTES,'UTF-8')?> – Collabs</title><style>html,body{height:100%;width:100%;margin:0;padding:0;background:#0f1117;color:#f5f7fb;font-family:Inter,system-ui,sans-serif;overflow:hidden}body{display:flex;flex-direction:column}.bar{height:52px;min-height:52px;box-sizing:border-box;display:flex;align-items:center;gap:12px;padding:0 16px;background:#171a23;border-bottom:1px solid #292e3b}.back{color:#cbd3e0;text-decoration:none}.title{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}.presence{margin-left:auto;color:#aeb8ca;font-size:13px}.editor{flex:1;min-height:0;width:100%;height:calc(100vh - 52px);overflow:hidden}.action{border:1px solid #303646;background:#141720;color:#cbd3e0;border-radius:8px;padding:7px 10px;cursor:pointer}.action:hover{background:#252a38}.danger{color:#ff9b9b;border-color:#63343a}.modal-backdrop{display:none;position:fixed;inset:0;background:#0009;z-index:1000;align-items:center;justify-content:center;padding:18px}.modal-backdrop.open{display:flex}.modal{width:min(460px,100%);background:#171a23;border:1px solid #303646;border-radius:14px;padding:20px}.setting{padding:12px 0;border-bottom:1px solid #292e3b}.setting-label{font-size:11px;text-transform:uppercase;color:#8993a6;letter-spacing:.06em}.setting-value{margin-top:4px}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}</style><script src="<?=BASE_URL?>/assets/js/accessibility-apply.js" defer></script></head><body><header class="bar"><a class="back" href="<?=htmlspecialchars(BASE_URL.'/modules/collaboration/server-coworkspaces.php?server_id='.(int)$workspace['server_id'],ENT_QUOTES,'UTF-8')?>">← Collabs</a><span class="title">📄 <?=htmlspecialchars((string)$document['title'],ENT_QUOTES,'UTF-8')?></span><span id="presence" class="presence">Checking collaborators…</span><button class="action" onclick="openSettings()">⚙ Settings</button><?php if($canDelete):?><button class="action danger" onclick="deleteDocument()">🗑 Delete</button><?php endif;?></header><div id="onlyoffice-editor" class="editor"></div><div id="settingsModal" class="modal-backdrop" onclick="if(event.target===this)closeSettings()"><div class="modal"><h3>Document settings</h3><div class="setting"><div class="setting-label">Access</div><div class="setting-value"><?=ucfirst((string)$document['visibility'])?> — <?=$document['visibility']==='private'?'Only explicitly shared users can access.':'All Coworkspace members can access.'?></div></div><div class="setting"><div class="setting-label">Your permission</div><div class="setting-value"><?=$canEdit?'Can edit':'View only'?></div></div><div class="setting"><div class="setting-label">Owner</div><div class="setting-value">User #<?=((int)$document['created_by'])?></div></div><div class="modal-actions"><button class="action" onclick="closeSettings()">Close</button><?php if($canDelete):?><button class="action danger" onclick="closeSettings();deleteDocument()">Delete document</button><?php endif;?></div></div></div><script src="<?=htmlspecialchars($documentServer,ENT_QUOTES,'UTF-8')?>/web-apps/apps/api/documents/api.js"></script><script>const OO_CONFIG=<?=json_encode($config,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?>,PRESENCE_API=<?=json_encode(BASE_URL.'/API/collaboration/document-presence.php')?>,DELETE_API=<?=json_encode(BASE_URL.'/API/collaboration/delete-document.php')?>,DOC_ID=<?=$documentId?>,WORKSPACE_ID=<?=$workspaceId?>,CSRF=<?=json_encode(AuthMiddleware::csrfToken())?>,CAN_DELETE=<?=$canDelete?'true':'false'?>;function openSettings(){document.getElementById('settingsModal').classList.add('open')}function closeSettings(){document.getElementById('settingsModal').classList.remove('open')}async function deleteDocument(){if(!CAN_DELETE||!confirm('Delete this document permanently?'))return;try{const r=await fetch(DELETE_API,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({document_id:DOC_ID,workspace_id:WORKSPACE_ID,csrf_token:CSRF})});const d=await r.json();if(!r.ok||!d.success)throw Error(d.error||'Unable to delete document.');location.href=<?=json_encode(BASE_URL.'/modules/collaboration/server-coworkspaces.php?server_id='.(int)$workspace['server_id'])?>}catch(e){alert(e.message)}}function updatePresence(){fetch(PRESENCE_API+'?document_id='+DOC_ID,{credentials:'same-origin'}).then(r=>r.json()).then(d=>{const p=d.presence||[];const editing=p.filter(x=>x.mode==='editing').length;document.getElementById('presence').textContent=p.length?(editing+' editing · '+(p.length-editing)+' viewing'):'Only you'}).catch(()=>{})}function heartbeat(){fetch(PRESENCE_API,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({document_id:DOC_ID,mode:OO_CONFIG.document.permissions.edit?'editing':'viewing',csrf_token:CSRF})}).then(updatePresence).catch(()=>{})}function initializeOnlyOffice(){if(!window.DocsAPI){document.getElementById('onlyoffice-editor').textContent='ONLYOFFICE editor could not be loaded.';return}OO_CONFIG.type=window.matchMedia('(max-width:768px)').matches?'mobile':'desktop';new DocsAPI.DocEditor('onlyoffice-editor',OO_CONFIG)}initializeOnlyOffice();heartbeat();setInterval(heartbeat,20000);setInterval(updatePresence,10000);</script></body></html>
